'use client';

import { useState } from 'react';
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react';
import { ChevronDownIcon } from '@heroicons/react/20/solid';
import type { PlannerEvent } from '@/types';
import { MONTHS_TR } from '@/lib/constants';
import { formatDate, isToday, getWeekDates } from '@/lib/dateUtils';

interface Props {
  currentWeekStart: Date;
  events: PlannerEvent[];
  onAddEvent: () => void;
}

const DAY_HEADERS = ['Pt', 'Sa', 'Ça', 'Pe', 'Cu', 'Ct', 'Pa'];

interface CalendarItem {
  id: string;
  icon: string;
  name: string;
  defaultChecked: boolean;
}

const MY_CALENDARS: CalendarItem[] = [
  { id: 'me', icon: '👤', name: 'Kişisel', defaultChecked: true },
  { id: 'task', icon: '🎯', name: 'Görevler', defaultChecked: true },
  { id: 'work', icon: '💼', name: 'İş', defaultChecked: true },
  { id: 'birthday', icon: '🎉', name: 'Doğum Günleri', defaultChecked: true },
  { id: 'reminder', icon: '🔔', name: 'Hatırlatıcılar', defaultChecked: false },
  { id: 'study', icon: '📚', name: 'Okul', defaultChecked: false },
];

const CATEGORIES = [
  { id: 'high', name: 'Yüksek Öncelik', color: '#ef4444' },
  { id: 'med', name: 'Orta Öncelik', color: '#f59e0b' },
  { id: 'low', name: 'Düşük Öncelik', color: '#3b82f6' },
];

export default function CalSidebar({ currentWeekStart, events, onAddEvent }: Props) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [otherOpen, setOtherOpen] = useState(false);
  const [calOpen, setCalOpen] = useState(true);
  const [catOpen, setCatOpen] = useState(true);
  const [checked, setChecked] = useState<Record<string, boolean>>(
    Object.fromEntries(MY_CALENDARS.map(c => [c.id, c.defaultChecked]))
  );

  const weekDateStrs = getWeekDates(currentWeekStart).map(d => formatDate(d));

  const base = new Date(currentWeekStart);
  base.setMonth(base.getMonth() + monthOffset);
  const year = base.getFullYear();
  const month = base.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);

  const startOffset = firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1;
  const prevMonthDays: number[] = [];
  for (let i = 0; i < startOffset; i++) {
    const d = new Date(year, month, -startOffset + i + 1);
    prevMonthDays.push(d.getDate());
  }

  const currentDays: { day: number; dStr: string; todayFlag: boolean; inWeek: boolean; hasEv: boolean }[] = [];
  for (let day = 1; day <= lastDay.getDate(); day++) {
    const d = new Date(year, month, day);
    const dStr = formatDate(d);
    currentDays.push({
      day,
      dStr,
      todayFlag: isToday(d),
      inWeek: weekDateStrs.includes(dStr),
      hasEv: events.some(e => e.date === dStr),
    });
  }

  const filled = startOffset + lastDay.getDate();
  const remaining = filled % 7 === 0 ? 0 : 7 - (filled % 7);
  const nextDays = Array.from({ length: remaining }, (_, i) => i + 1);

  const toggle = (id: string) => setChecked(c => ({ ...c, [id]: !c[id] }));

  return (
    <aside className="w-[260px] shrink-0 self-stretch bg-white border border-slate-200 rounded-2xl shadow-sm p-4 overflow-y-auto">
      {/* Mini Calendar */}
      <div className="flex items-center justify-between mb-3">
        <span className="text-sm font-bold text-slate-800">{MONTHS_TR[month]} {year}</span>
        <div className="flex gap-1">
          <button
            onClick={() => setMonthOffset(o => o - 1)}
            className="w-7 h-7 rounded-lg text-slate-500 hover:bg-slate-100 hover:text-slate-900 flex items-center justify-center transition-colors"
            aria-label="Önceki ay"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
          <button
            onClick={() => setMonthOffset(o => o + 1)}
            className="w-7 h-7 rounded-lg text-slate-500 hover:bg-slate-100 hover:text-slate-900 flex items-center justify-center transition-colors"
            aria-label="Sonraki ay"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>
      <div className="grid grid-cols-7 gap-0.5 mb-5">
        {DAY_HEADERS.map(h => (
          <div key={h} className="text-center text-[0.65rem] font-bold text-slate-400 uppercase py-1">{h}</div>
        ))}
        {prevMonthDays.map((d, i) => (
          <div key={`prev-${i}`} className="text-center text-[0.75rem] text-slate-300 py-1.5">{d}</div>
        ))}
        {currentDays.map(({ day, dStr, todayFlag, inWeek, hasEv }) => {
          const cls =
            'text-center text-[0.75rem] py-1.5 rounded-lg cursor-pointer transition-colors font-medium leading-none flex flex-col items-center justify-center ' +
            (todayFlag
              ? 'bg-indigo-500 text-white font-bold'
              : inWeek
              ? 'bg-indigo-50 text-indigo-600'
              : 'text-slate-700 hover:bg-slate-100');
          return (
            <div key={dStr} className={cls}>
              <span>{day}</span>
              {hasEv && <span className={`block w-1 h-1 rounded-full mt-0.5 ${todayFlag ? 'bg-white' : 'bg-indigo-500'}`} />}
            </div>
          );
        })}
        {nextDays.map((d, i) => (
          <div key={`next-${i}`} className="text-center text-[0.75rem] text-slate-300 py-1.5">{d}</div>
        ))}
      </div>

      {/* Scheduled */}
      <div className="flex items-center justify-between py-2 px-1 border-t border-slate-100">
        <span className="text-sm font-bold text-slate-800">Planlanan</span>
        <button
          onClick={onAddEvent}
          title="Etkinlik ekle"
          className="w-6 h-6 rounded-md text-slate-500 hover:bg-indigo-500 hover:text-white flex items-center justify-center transition-colors"
        >
          <Plus className="w-4 h-4" />
        </button>
      </div>

      {/* My Calendars */}
      <Section title="Takvimlerim" open={calOpen} onToggle={() => setCalOpen(o => !o)}>
        {MY_CALENDARS.map(c => (
          <label key={c.id} className="flex items-center gap-2.5 py-1.5 px-2 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
            <input
              type="checkbox"
              checked={!!checked[c.id]}
              onChange={() => toggle(c.id)}
              className="w-4 h-4 accent-indigo-500 cursor-pointer"
            />
            <span className="text-base leading-none">{c.icon}</span>
            <span className="text-sm font-medium text-slate-800 flex-1 truncate">{c.name}</span>
          </label>
        ))}
        <button className="block w-full text-left px-2 py-1.5 mt-1 rounded-lg text-xs font-semibold text-indigo-600 hover:bg-indigo-50 transition-colors">
          + Yeni Ekle
        </button>
      </Section>

      {/* Other Calendars */}
      <Section title="Diğer Takvimler" open={otherOpen} onToggle={() => setOtherOpen(o => !o)}>
        <p className="text-xs text-slate-400 px-2 py-1.5">Şimdilik boş</p>
      </Section>

      {/* Categories */}
      <Section title="Kategoriler" open={catOpen} onToggle={() => setCatOpen(o => !o)}>
        {CATEGORIES.map(c => (
          <div key={c.id} className="flex items-center gap-2.5 py-1.5 px-2 rounded-lg">
            <span className="w-2 h-2 rounded-full shrink-0" style={{ background: c.color }} />
            <span className="text-sm font-medium text-slate-800 flex-1">{c.name}</span>
          </div>
        ))}
      </Section>
    </aside>
  );
}

function Section({
  title, open, onToggle, children,
}: {
  title: string;
  open: boolean;
  onToggle: () => void;
  children: React.ReactNode;
}) {
  return (
    <div className="border-t border-slate-100 pt-1 pb-1">
      <button
        onClick={onToggle}
        aria-expanded={open}
        className="w-full flex items-center justify-between py-2 px-1 hover:text-indigo-600 transition-colors"
      >
        <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">{title}</span>
        <ChevronDownIcon className={`w-4 h-4 text-slate-400 transition-transform ${open ? '' : '-rotate-90'}`} />
      </button>
      {open && <div className="flex flex-col">{children}</div>}
    </div>
  );
}
