'use client';

import { ChevronLeft, ChevronRight, ListFilter, List, Info } from 'lucide-react';
import { PlusIcon } from '@heroicons/react/24/solid';
import { MONTHS_TR, DAYS_TR } from '@/lib/constants';
import type { CalendarView } from '@/components/TopBar';

interface Props {
  view: CalendarView;
  anchorDate: Date;
  onToday: () => void;
  onPrev: () => void;
  onNext: () => void;
  onTour: () => void;
  onAddEvent: () => void;
}

function buildTitle(view: CalendarView, d: Date): string {
  if (view === 'day') {
    const dayName = DAYS_TR[d.getDay() === 0 ? 6 : d.getDay() - 1];
    return `${d.getDate()} ${MONTHS_TR[d.getMonth()]} ${d.getFullYear()} • ${dayName}`;
  }
  if (view === 'month') {
    return `${MONTHS_TR[d.getMonth()]} ${d.getFullYear()}`;
  }
  // week
  return `${MONTHS_TR[d.getMonth()]} ${d.getFullYear()}`;
}

export default function CalMainHeader({ view, anchorDate, onToday, onPrev, onNext, onTour, onAddEvent }: Props) {
  const title = buildTitle(view, anchorDate);

  return (
    <div className="flex items-center justify-between px-5 py-4 bg-white border-b border-slate-200 rounded-t-2xl">
      <div className="flex items-center gap-3.5">
        <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">{title}</h2>
        <div className="flex gap-1">
          <button
            onClick={onPrev}
            aria-label="Önceki"
            className="w-8 h-8 rounded-lg border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
          <button
            onClick={onNext}
            aria-label="Sonraki"
            className="w-8 h-8 rounded-lg border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>

      <div className="flex items-center gap-2">
        <button
          onClick={onToday}
          className="px-4 py-1.5 rounded-lg border border-slate-200 bg-white text-sm font-semibold text-slate-700 hover:bg-slate-50 transition-colors"
        >
          Bugün
        </button>
        <button
          aria-label="Filtre"
          title="Filtre"
          className="w-8 h-8 rounded-lg border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
        >
          <ListFilter className="w-4 h-4" />
        </button>
        <button
          aria-label="Liste görünümü"
          title="Liste görünümü"
          className="w-8 h-8 rounded-lg border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
        >
          <List className="w-4 h-4" />
        </button>
        <button
          onClick={onTour}
          aria-label="Rehber"
          title="Rehber"
          className="w-8 h-8 rounded-lg border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
        >
          <Info className="w-4 h-4" />
        </button>
        <button
          onClick={onAddEvent}
          className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-indigo-600 text-white text-sm font-bold hover:bg-indigo-500 active:bg-indigo-700 shadow-sm hover:shadow-md transition-all"
        >
          <PlusIcon className="w-4 h-4" />
          <span>Etkinlik Ekle</span>
        </button>
      </div>
    </div>
  );
}
