'use client';

import type { PlannerEvent } from '@/types';
import type { CalendarView } from '@/components/TopBar';
import { DAYS_SHORT } from '@/lib/constants';
import { START_HOUR, END_HOUR, HOUR_HEIGHT } from '@/lib/constants';
import { isToday, isPast, formatDate, getWeekDates } from '@/lib/dateUtils';

interface Props {
  view: CalendarView;
  anchorDate: Date;
  events: PlannerEvent[];
  deleteMode: boolean;
  onEventClick: (id: string) => void;
  onDeleteEvent: (id: string) => void;
  getBirthdayBanners?: (dateStr: string) => { name: string }[];
}

export default function CalendarSection(props: Props) {
  if (props.view === 'day') return <DayView {...props} />;
  if (props.view === 'month') return <MonthView {...props} />;
  return <WeekView {...props} />;
}

/* ===================== WEEK ===================== */
function WeekView({
  anchorDate, events, deleteMode, onEventClick, onDeleteEvent, getBirthdayBanners,
}: Props) {
  const dates = getWeekDates(anchorDate);

  return (
    <section className="bg-white border border-slate-200 border-t-0 rounded-b-2xl shadow-sm overflow-hidden">
      {/* Day headers */}
      <div className="grid grid-cols-[60px_repeat(7,1fr)] border-b border-slate-200 bg-white">
        <div className="py-3 px-2 text-[0.7rem] text-slate-400 text-center">Saat</div>
        {dates.map((d, i) => {
          const today = isToday(d);
          const past = isPast(d) && !today;
          return (
            <div
              key={i}
              className={`py-3 px-2 text-center border-l border-slate-200 ${past ? 'opacity-50' : ''}`}
            >
              <span className="block text-[0.72rem] font-semibold text-slate-400 uppercase tracking-wider">
                {DAYS_SHORT[i]}
              </span>
              <span
                className={
                  'inline-flex items-center justify-center w-8 h-8 rounded-full text-base font-bold mt-1 ' +
                  (today ? 'bg-indigo-500 text-white' : 'text-slate-800')
                }
              >
                {d.getDate()}
              </span>
            </div>
          );
        })}
      </div>

      {/* Body */}
      <div
        className={`grid grid-cols-[60px_repeat(7,1fr)] max-h-[540px] overflow-y-auto ${deleteMode ? 'delete-mode' : ''}`}
      >
        {/* Time labels */}
        <div className="border-r border-slate-100">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }, (_, i) => (
            <div
              key={i}
              className="text-[0.7rem] text-slate-400 text-right pr-2 pt-1"
              style={{ height: HOUR_HEIGHT }}
            >
              {String(START_HOUR + i).padStart(2, '0')}:00
            </div>
          ))}
        </div>

        {/* Day columns */}
        {dates.map((d, dayIdx) => {
          const dateStr = formatDate(d);
          const today = isToday(d);
          const past = isPast(d) && !today;
          const bdays = getBirthdayBanners ? getBirthdayBanners(dateStr) : [];
          const dayEvents = events.filter(e => e.date === dateStr && e.moduleType !== 'birthday');

          return (
            <div
              key={dayIdx}
              className={`relative border-l border-slate-100 ${
                today ? 'bg-indigo-50/30' : past ? 'bg-slate-50/40' : 'bg-white'
              }`}
              style={{ minHeight: (END_HOUR - START_HOUR + 1) * HOUR_HEIGHT }}
              data-date={dateStr}
            >
              {bdays.map((b, bi) => (
                <div key={bi} className="bday-banner">🎂 {b.name}</div>
              ))}
              {Array.from({ length: END_HOUR - START_HOUR + 1 }, (_, i) => (
                <div
                  key={i}
                  className="absolute left-0 right-0 h-px bg-slate-100"
                  style={{ top: i * HOUR_HEIGHT }}
                />
              ))}
              {dayEvents.map(ev => (
                <EventCard
                  key={ev.id}
                  ev={ev}
                  deleteMode={deleteMode}
                  onClick={() => onEventClick(ev.id)}
                  onDelete={() => onDeleteEvent(ev.id)}
                />
              ))}
            </div>
          );
        })}
      </div>
    </section>
  );
}

/* ===================== DAY ===================== */
function DayView({
  anchorDate, events, deleteMode, onEventClick, onDeleteEvent, getBirthdayBanners,
}: Props) {
  const d = anchorDate;
  const dateStr = formatDate(d);
  const today = isToday(d);
  const dayName = DAYS_SHORT[(d.getDay() === 0 ? 6 : d.getDay() - 1)];
  const dayEvents = events.filter(e => e.date === dateStr && e.moduleType !== 'birthday');
  const bdays = getBirthdayBanners ? getBirthdayBanners(dateStr) : [];

  return (
    <section className="bg-white border border-slate-200 border-t-0 rounded-b-2xl shadow-sm overflow-hidden">
      <div className="grid grid-cols-[60px_1fr] border-b border-slate-200 bg-white">
        <div className="py-3 px-2 text-[0.7rem] text-slate-400 text-center">Saat</div>
        <div className="py-3 px-2 text-center border-l border-slate-200">
          <span className="block text-[0.72rem] font-semibold text-slate-400 uppercase tracking-wider">
            {dayName}
          </span>
          <span
            className={
              'inline-flex items-center justify-center w-8 h-8 rounded-full text-base font-bold mt-1 ' +
              (today ? 'bg-indigo-500 text-white' : 'text-slate-800')
            }
          >
            {d.getDate()}
          </span>
        </div>
      </div>

      <div
        className={`grid grid-cols-[60px_1fr] max-h-[640px] overflow-y-auto ${deleteMode ? 'delete-mode' : ''}`}
      >
        <div className="border-r border-slate-100">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }, (_, i) => (
            <div
              key={i}
              className="text-[0.7rem] text-slate-400 text-right pr-2 pt-1"
              style={{ height: HOUR_HEIGHT }}
            >
              {String(START_HOUR + i).padStart(2, '0')}:00
            </div>
          ))}
        </div>

        <div
          className={`relative border-l border-slate-100 ${today ? 'bg-indigo-50/30' : 'bg-white'}`}
          style={{ minHeight: (END_HOUR - START_HOUR + 1) * HOUR_HEIGHT }}
          data-date={dateStr}
        >
          {bdays.map((b, bi) => (
            <div key={bi} className="bday-banner">🎂 {b.name}</div>
          ))}
          {Array.from({ length: END_HOUR - START_HOUR + 1 }, (_, i) => (
            <div
              key={i}
              className="absolute left-0 right-0 h-px bg-slate-100"
              style={{ top: i * HOUR_HEIGHT }}
            />
          ))}
          {dayEvents.length === 0 ? (
            <div className="absolute inset-0 flex items-center justify-center text-sm text-slate-400">
              Bu gün için planlanmış etkinlik yok.
            </div>
          ) : (
            dayEvents.map(ev => (
              <EventCard
                key={ev.id}
                ev={ev}
                wide
                deleteMode={deleteMode}
                onClick={() => onEventClick(ev.id)}
                onDelete={() => onDeleteEvent(ev.id)}
              />
            ))
          )}
        </div>
      </div>
    </section>
  );
}

/* ===================== MONTH ===================== */
function MonthView({
  anchorDate, events, deleteMode, onEventClick, onDeleteEvent,
}: Props) {
  const year = anchorDate.getFullYear();
  const month = anchorDate.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startOffset = firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1;
  const totalCells = Math.ceil((startOffset + lastDay.getDate()) / 7) * 7;

  const cells: { date: Date; inMonth: boolean }[] = [];
  for (let i = 0; i < totalCells; i++) {
    const d = new Date(year, month, i - startOffset + 1);
    cells.push({ date: d, inMonth: d.getMonth() === month });
  }

  return (
    <section className="bg-white border border-slate-200 border-t-0 rounded-b-2xl shadow-sm overflow-hidden">
      {/* Header row */}
      <div className="grid grid-cols-7 border-b border-slate-200 bg-white">
        {DAYS_SHORT.map(d => (
          <div
            key={d}
            className="py-3 text-center text-[0.72rem] font-semibold text-slate-400 uppercase tracking-wider border-l first:border-l-0 border-slate-200"
          >
            {d}
          </div>
        ))}
      </div>

      {/* Month grid */}
      <div className="grid grid-cols-7 auto-rows-[110px]">
        {cells.map(({ date, inMonth }, i) => {
          const dStr = formatDate(date);
          const today = isToday(date);
          const past = isPast(date) && !today;
          const dayEvents = events.filter(e => e.date === dStr && e.moduleType !== 'birthday');
          return (
            <div
              key={i}
              className={
                'border-l border-t border-slate-100 first:border-l-0 p-1.5 flex flex-col gap-1 overflow-hidden ' +
                (!inMonth ? 'bg-slate-50/40 ' : '') +
                (today ? 'bg-indigo-50/40 ' : past && inMonth ? 'bg-white ' : '') +
                (i < 7 ? 'border-t-0 ' : '')
              }
            >
              <div className="flex items-center justify-between">
                <span
                  className={
                    'inline-flex items-center justify-center w-6 h-6 rounded-full text-xs font-bold ' +
                    (today
                      ? 'bg-indigo-500 text-white'
                      : !inMonth
                      ? 'text-slate-300'
                      : past
                      ? 'text-slate-400'
                      : 'text-slate-700')
                  }
                >
                  {date.getDate()}
                </span>
                {dayEvents.length > 3 && (
                  <span className="text-[0.6rem] font-semibold text-slate-400">
                    +{dayEvents.length - 3}
                  </span>
                )}
              </div>
              <div className="flex flex-col gap-0.5 overflow-hidden">
                {dayEvents.slice(0, 3).map(ev => {
                  const colorMap: Record<string, string> = {
                    high: 'bg-red-50 text-red-700 border-l-red-500',
                    medium: 'bg-orange-50 text-orange-700 border-l-orange-500',
                    low: 'bg-blue-50 text-blue-700 border-l-blue-500',
                  };
                  const cmpCls = ev.completed
                    ? 'bg-green-50 !text-green-700 border-l-green-500 line-through'
                    : '';
                  return (
                    <button
                      key={ev.id}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (deleteMode) onDeleteEvent(ev.id);
                        else onEventClick(ev.id);
                      }}
                      className={`text-left text-[0.65rem] font-semibold px-1.5 py-0.5 rounded-sm border-l-2 truncate hover:brightness-95 transition ${colorMap[ev.importance]} ${cmpCls}`}
                      title={`${ev.startTime} ${ev.name}`}
                    >
                      <span className="opacity-70 mr-1">{ev.startTime}</span>
                      {ev.name}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

/* ===================== EVENT CARD (week/day) ===================== */
function EventCard({
  ev, deleteMode, onClick, onDelete, wide,
}: {
  ev: PlannerEvent;
  deleteMode: boolean;
  onClick: () => void;
  onDelete: () => void;
  wide?: boolean;
}) {
  const [sh, sm] = ev.startTime.split(':').map(Number);
  const [eh, em] = ev.endTime.split(':').map(Number);
  const startH = sh + sm / 60;
  const endH = eh + em / 60;
  const top = (startH - START_HOUR) * HOUR_HEIGHT;
  const height = Math.max((endH - startH) * HOUR_HEIGHT, 28);
  const impCls = ev.importance === 'high' ? 'imp-high' : ev.importance === 'medium' ? 'imp-med' : 'imp-low';
  const completedCls = ev.completed ? ' completed' : '';
  const ppCount = ev.postponeCount || 0;
  const ppClass = ppCount >= 3 ? ' chronic-postpone' : ppCount >= 1 ? ' postponed' : '';

  return (
    <div
      className={`event-card ${impCls}${completedCls}${ppClass}`}
      style={{ top, height, left: wide ? 8 : undefined, right: wide ? 8 : undefined }}
      data-id={ev.id}
      onClick={onClick}
    >
      {ppCount > 0 && (
        <div className="postpone-badge" title={`${ppCount} kez ertelendi`}>
          🔄{ppCount}
        </div>
      )}
      <span className="event-name">{ev.name}</span>
      <span className="event-time">{ev.startTime} - {ev.endTime}</span>
      {deleteMode && (
        <div
          className="delete-badge"
          onClick={e => { e.stopPropagation(); onDelete(); }}
        >
          ✕
        </div>
      )}
    </div>
  );
}
