'use client';

import { useState } from 'react';
import { Search, HelpCircle } from 'lucide-react';
import { BellIcon } from '@heroicons/react/24/outline';

export type CalendarView = 'day' | 'week' | 'month';

interface Props {
  view: CalendarView;
  onViewChange: (v: CalendarView) => void;
  onProfile: () => void;
  userName?: string | null;
}

const VIEW_LABELS: Record<CalendarView, string> = {
  day: 'Gün',
  week: 'Hafta',
  month: 'Ay',
};

export default function TopBar({ view, onViewChange, onProfile, userName }: Props) {
  const [search, setSearch] = useState('');

  return (
    <div className="flex items-center gap-4 bg-white border border-slate-200 rounded-2xl px-4 py-2.5 shadow-sm">
      {/* View toggle */}
      <div className="inline-flex items-center gap-1 bg-slate-100 border border-slate-200 rounded-xl p-1">
        {(['day', 'week', 'month'] as CalendarView[]).map(v => (
          <button
            key={v}
            onClick={() => onViewChange(v)}
            className={
              'px-4 py-1.5 rounded-lg text-sm font-semibold transition-colors ' +
              (view === v
                ? 'bg-white text-slate-900 shadow-sm'
                : 'text-slate-500 hover:text-slate-900')
            }
          >
            {VIEW_LABELS[v]}
          </button>
        ))}
      </div>

      {/* Search */}
      <div className="flex-1 max-w-xl flex items-center gap-2 bg-slate-100 border border-slate-200 rounded-xl px-3.5 py-2 focus-within:border-indigo-500 focus-within:ring-2 focus-within:ring-indigo-100 transition">
        <Search className="w-4 h-4 text-slate-400 shrink-0" strokeWidth={2} />
        <input
          type="text"
          placeholder="Ara..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="flex-1 bg-transparent border-none outline-none text-sm text-slate-800 placeholder:text-slate-400"
        />
      </div>

      {/* Right actions */}
      <div className="flex items-center gap-2 ml-auto">
        <button
          aria-label="Bildirimler"
          title="Bildirimler"
          className="w-9 h-9 rounded-xl border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
        >
          <BellIcon className="w-[18px] h-[18px]" strokeWidth={2} />
        </button>
        <button
          aria-label="Yardım"
          title="Yardım"
          className="w-9 h-9 rounded-xl border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 hover:text-slate-900 flex items-center justify-center transition-colors"
        >
          <HelpCircle className="w-[18px] h-[18px]" strokeWidth={2} />
        </button>
        <button
          onClick={onProfile}
          title="Profil"
          className="flex items-center gap-2.5 pl-1 pr-3 py-1 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 transition-colors"
        >
          <div className="w-8 h-8 rounded-full bg-gradient-to-br from-indigo-500 to-violet-500 text-white flex items-center justify-center font-bold text-sm">
            {(userName || 'M').charAt(0).toUpperCase()}
          </div>
          <div className="flex flex-col items-start leading-tight">
            <span className="text-[0.82rem] font-bold text-slate-800">{userName || 'Misafir'}</span>
            <span className="text-[0.68rem] text-slate-400 mt-0.5">{userName ? 'Üye' : 'Giriş yap'}</span>
          </div>
        </button>
      </div>
    </div>
  );
}
